"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Label } from "./label";

interface FieldContextValue {
  id: string;
  describedBy?: string;
  invalid: boolean;
  disabled: boolean;
}

const FieldContext = React.createContext<FieldContextValue | null>(null);

/** Geeft de omliggende Field-context terug (id, aria-koppelingen, foutstatus). */
export function useFieldContext() {
  return React.useContext(FieldContext);
}

export interface FieldProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "id"> {
  label?: React.ReactNode;
  /** Uitleg onder het veld. */
  hint?: React.ReactNode;
  /** Foutmelding; zet het veld automatisch in foutstatus. */
  error?: React.ReactNode;
  required?: boolean;
  disabled?: boolean;
  /** Extra element rechts van het label (bv. een Badge of "optioneel"). */
  labelAction?: React.ReactNode;
  id?: string;
  /** Horizontale layout: label links, veld rechts. */
  orientation?: "vertical" | "horizontal";
  /**
   * Zwevend label: het label staat in het veld en klimt naar de rand zodra er
   * focus of inhoud is. Werkt met Input, Textarea, Select en PhoneInput.
   */
  floating?: boolean;
  /** Bij een zwevend label: of er al iets ingevuld staat. */
  filled?: boolean;
}

/**
 * Field — koppelt label, hint en foutmelding aan één invoerelement.
 * Kinderen krijgen automatisch `id`, `aria-describedby` en `aria-invalid`.
 */
export const Field = React.forwardRef<HTMLDivElement, FieldProps>(function Field(
  {
    label,
    hint,
    error,
    required,
    disabled,
    labelAction,
    id,
    orientation = "vertical",
    floating,
    filled,
    className,
    children,
    ...rest
  },
  ref
) {
  const autoId = React.useId();
  const fieldId = id ?? `lui-field-${autoId}`;
  const hintId = hint ? `${fieldId}-hint` : undefined;
  const errorId = error ? `${fieldId}-error` : undefined;
  const describedBy = [errorId, hintId].filter(Boolean).join(" ") || undefined;

  const context: FieldContextValue = {
    id: fieldId,
    describedBy,
    invalid: Boolean(error),
    disabled: Boolean(disabled),
  };

  return (
    <FieldContext.Provider value={context}>
      <div
        ref={ref}
        className={cn(
          "lui-field",
          `lui-field-${orientation}`,
          floating && "lui-field-floating",
          disabled && "lui-field-disabled",
          className
        )}
        data-filled={filled ? "" : undefined}
        {...rest}
      >
        {floating ? (
          <div className="lui-field-control">
            {children}
            {label && (
              <Label htmlFor={fieldId} required={required} className="lui-field-floatlabel">
                {label}
              </Label>
            )}
            {error && (
              <span className="lui-field-error" id={errorId} role="alert">
                {error}
              </span>
            )}
            {hint && !error && (
              <span className="lui-field-hint" id={hintId}>
                {hint}
              </span>
            )}
          </div>
        ) : (
          <>
        {(label || labelAction) && (
          <div className="lui-field-labelrow">
            {label && (
              <Label htmlFor={fieldId} required={required}>
                {label}
              </Label>
            )}
            {labelAction && <span className="lui-field-labelaction">{labelAction}</span>}
          </div>
        )}
        <div className="lui-field-control">
          {children}
          {error && (
            <span className="lui-field-error" id={errorId} role="alert">
              {error}
            </span>
          )}
          {hint && !error && (
            <span className="lui-field-hint" id={hintId}>
              {hint}
            </span>
          )}
        </div>
          </>
        )}
      </div>
    </FieldContext.Provider>
  );
});

/** Zet Field-context om naar props voor een invoerelement. */
export function useFieldProps(props: {
  id?: string;
  disabled?: boolean;
  invalid?: boolean;
  "aria-describedby"?: string;
}) {
  const context = useFieldContext();
  if (!context) return props;
  return {
    ...props,
    id: props.id ?? context.id,
    disabled: props.disabled ?? context.disabled,
    invalid: props.invalid ?? context.invalid,
    "aria-describedby": props["aria-describedby"] ?? context.describedBy,
  };
}

/* ============================ Field ============================ */
.lui-field { display: flex; flex-direction: column; gap: 7px; min-width: 0; }
.lui-field-labelrow { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.lui-field-labelaction { font-size: var(--fs-sm); color: var(--text-3); }
.lui-field-control { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.lui-field-hint { font-size: var(--fs-sm); color: var(--text-3); line-height: 1.45; }
.lui-field-error { font-size: var(--fs-sm); color: var(--red); line-height: 1.45; font-weight: 550; }
.lui-field-disabled { opacity: .6; }

.lui-field-horizontal {
  flex-direction: row; align-items: flex-start; gap: 20px;
}
.lui-field-horizontal .lui-field-labelrow { width: 200px; flex: none; padding-top: 11px; }
.lui-field-horizontal .lui-field-control { flex: 1; }

/* ---------- Zwevend label ---------- */
/* Het label ligt over het veld en klimt naar de rand bij focus of inhoud.
   :placeholder-shown doet het werk, dus het veld heeft een placeholder nodig
   (desnoods een spatie) — geen JavaScript nodig om te weten of er iets staat. */
.lui-field-floating .lui-field-control { position: relative; }
.lui-field-floating .lui-field-floatlabel {
  position: absolute; top: 0; inset-inline-start: 11px;
  padding: 0 4px; pointer-events: none;
  background: var(--surface); color: var(--text-3);
  font-size: 12px; line-height: 1;
  transform: translateY(-50%);
  transition: transform var(--dur-fast) var(--ease), font-size var(--dur-fast), color var(--dur-fast);
}
/* Leeg en zonder focus: het label staat middenin het veld. Een telefoonveld is
   nooit echt leeg — het landnummer staat er al — dus dat sluiten we uit, anders
   valt het label over de landkiezer heen. */
.lui-field-floating:not([data-filled])
  .lui-field-control:has(:placeholder-shown:not(:focus)):not(:has(.lui-phone))
  .lui-field-floatlabel {
  top: calc(21px * var(--density));
  font-size: var(--fs-base);
  transform: translateY(-50%);
  background: transparent;
}
.lui-field-floating .lui-field-control:focus-within .lui-field-floatlabel { color: var(--accent); }
.lui-field-floating .lui-field-control:has([aria-invalid="true"]) .lui-field-floatlabel { color: var(--red); }

/* De placeholder zelf blijft weg zolang het label er nog overheen ligt. */
.lui-field-floating .lui-field-control :is(input, textarea)::placeholder { color: transparent; }
.lui-field-floating .lui-field-control :is(input, textarea):focus::placeholder { color: var(--text-3); }

@media (prefers-reduced-motion: reduce) {
  .lui-field-floating .lui-field-floatlabel { transition: none; }
}
